37	    return (
38	      <Button size="sm" variant="outline" render={<Link href={cta.href} />}>
39	        {cta.label}
40	      </Button>
41	    )
42	  }
43	  return (
44	    <Button size="sm" variant="outline" onClick={cta.onClick}>
45	      {cta.label}
46	    </Button>
