50	export function EmptyState({
51	  icon: Icon,
52	  title,
53	  description,
54	  cta,
55	  ctaSecondary,
56	}: EmptyStateProps) {
57	  return (
58	    <div className="flex flex-col items-center justify-center py-16 text-center">
59	      <div className="mb-4 rounded-xl bg-muted/50 p-4">
60	        <Icon className="mx-auto h-12 w-12 text-muted-foreground/40" aria-hidden="true" />
61	      </div>
62	      <h3 className="mb-1 text-base font-semibold">{title}</h3>
63	      {description && (
64	        <p className="mb-6 max-w-[280px] text-sm text-muted-foreground">{description}</p>
65	      )}
66	      {(cta ?? ctaSecondary) && (
67	        <div className="flex flex-wrap items-center justify-center gap-2">
68	          {cta && <CtaButton cta={cta} />}
69	          {ctaSecondary && <SecondaryCtaButton cta={ctaSecondary} />}
70	        </div>
71	      )}
72	    </div>
73	  )
74	}
